content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --transition: all 0.2s ease-in-out;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-main: #f8fafc;
    --text-muted: #94a3b8;
    --border-color: #334155;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.18);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 1000px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 16px;
}

.title {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.025em;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow);
  padding: 20px;
  margin-bottom: 24px;
}

.stats-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.stat-item {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 500;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-color);
}

.chart-container {
  width: 100%;
  height: 400px;
  margin-top: 10px;
}

.footer {
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-muted);
  padding: 16px 0;
  border-top: 1px solid var(--border-color);
  margin-top: auto;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 18px;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: 8px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: var(--transition);
  background-color: #e2e8f0;
  color: var(--text-main);
}

.btn:hover {
  background-color: #cbd5e1;
}

.btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

@media (max-width: 640px) {
  .app-container {
    padding: 12px 8px;
  }

  .title {
    font-size: 1.4rem;
  }

  .chart-container {
    height: 300px;
  }

  .header {
    flex-direction: column;
    align-items: stretch;
  }

  .btn {
    width: 100%;
  }
}

import { useState } from 'react';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';
import './index.css';

interface MonthlySales {
  month: string;
  sales: number;
}

const generateInitialData = (): MonthlySales[] => {
  const months = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];
  // 実際のビジネスデータの傾向（3月の決算期や12月の繁忙期など）を反映した季節変動係数
  const seasonalFactors = [1.0, 0.8, 1.3, 1.0, 1.1, 1.0, 0.9, 1.0, 1.0, 1.1, 1.2, 1.4];

  return months.map((month, index) => {
    const factor = seasonalFactors[index];
    const base = Math.floor(Math.random() * 300 + 300) * 10000;
    const sales = Math.round(base * factor);
    return {
      month,
      sales,
    };
  });
};

export default function App() {
  const [data, setData] = useState<MonthlySales[]>(generateInitialData());
  const [isLoading, setIsLoading] = useState<boolean>(false);

  const handleRegenerate = () => {
    setIsLoading(true);
    setTimeout(() => {
      setData(generateInitialData());
      setIsLoading(false);
    }, 400);
  };

  const totalSales = data.reduce((sum, item) => sum + item.sales, 0);
  const averageSales = Math.round(totalSales / data.length);

  const formatYAxis = (value: number) => {
    return `${value / 10000}万`;
  };

  const formatTooltip = (value: number) => {
    return [`${value.toLocaleString()} 円`, '売上'];
  };

  return (
    <div className="app-container">
      <div>
        <header className="header">
          <div>
            <h1 className="title">年間売上ダッシュボード</h1>
            <p className="subtitle">1月〜12月の月別売上実績と推移</p>
          </div>
          <button 
            className="btn btn-primary" 
            onClick={handleRegenerate}
            disabled={isLoading}
          >
            {isLoading ? '生成中...' : 'データを再生成'}
          </button>
        </header>

        <div className="stats-container">
          <div className="stat-item">
            <span className="stat-label">年間合計売上</span>
            <span className="stat-value">{totalSales.toLocaleString()} 円</span>
          </div>
          <div className="stat-item">
            <span className="stat-label">月平均売上</span>
            <span className="stat-value">{averageSales.toLocaleString()} 円</span>
          </div>
        </div>

        <div className="card">
          <div 
            className="chart-container" 
            style={{ opacity: isLoading ? 0.4 : 1, transition: 'opacity 0.2s ease-in-out' }}
          >
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={data} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="month" stroke="#64748b" fontSize={12} tickLine={false} />
                <YAxis stroke="#64748b" fontSize={12} tickLine={false} tickFormatter={formatYAxis} />
                <Tooltip
                  formatter={formatTooltip}
                  contentStyle={{
                    backgroundColor: '#ffffff',
                    borderRadius: '8px',
                    border: '1px solid #e2e8f0',
                    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                  }}
                />
                <Bar dataKey="sales" fill="#4f46e5" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <footer className="footer">
        <p>&copy; 2025 年間売上ダッシュボードアプリケーション</p>
      </footer>
    </div>
  );
}
